// Package: Azure.Security.KeyVault.Secrets
// Install: dotnet add package Azure.Security.KeyVault.Secrets

using Azure.Security.KeyVault.Secrets;
using Azure.Identity;
using Microsoft.Extensions.Caching.Memory;

public class KeyVaultSecretService
{
    private readonly SecretClient _client;
    private readonly MemoryCache _cache;

    public KeyVaultSecretService(SecretClient client)
    {
        _client = client;
        _cache = new MemoryCache(new MemoryCacheOptions());
    }

    public async Task<string> GetSecretAsync(string name, CancellationToken ct = default)
    {
        try
        {
            // Check in-memory cache first to avoid throttling
            if (_cache.TryGetValue(name, out string? cached))
                return cached ?? string.Empty;

            KeyVaultSecret secret = await _client.GetSecretAsync(name, ct);
            _cache.Set(name, secret.Value, TimeSpan.FromMinutes(10));
            Console.WriteLine($"Retrieved secret '{name}' from Key Vault");
            return secret.Value;
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Failed to get secret '{name}': {ex.Message}");
            throw;
        }
    }
}

// Usage
var keyVaultUri = new Uri("https://aspnet-azure-kv.vault.azure.net/");
var client = new SecretClient(keyVaultUri, new DefaultAzureCredential());
var service = new KeyVaultSecretService(client);
string connectionString = await service.GetSecretAsync("ConnectionStrings--Default");

// Expected output:
// Retrieved secret 'ConnectionStrings--Default' from Key Vault

// Package: Azure.Extensions.AspNetCore.Configuration.KeyVault
// Install: dotnet add package Azure.Extensions.AspNetCore.Configuration.KeyVault

using Azure.Identity;
using Azure.Extensions.AspNetCore.Configuration.KeyVault;

var builder = WebApplication.CreateBuilder(args);

// Add Key Vault as a configuration source
// Secret names like 'ConnectionStrings--Default' map to 'ConnectionStrings:Default'
var keyVaultUri = new Uri(builder.Configuration["KeyVault:Uri"]!);
builder.Configuration.AddAzureKeyVault(keyVaultUri, new DefaultAzureCredential());

// Now secrets are available through the standard configuration pipeline
var connectionString = builder.Configuration.GetConnectionString("Default");
Console.WriteLine($"Connection string loaded, length: {connectionString?.Length ?? 0}");

// Expected output:
// Connection string loaded, length: 47

