using Azure.Security.KeyVault.Secrets;
using Microsoft.Extensions.Caching.Memory;

public class SecretCache
{
    private readonly SecretClient _client;
    private readonly MemoryCache _cache = new(new MemoryCacheOptions());

    public SecretCache(SecretClient client) => _client = client;

    public async Task<string> GetAsync(string name, CancellationToken ct = default)
    {
        try
        {
            return await _cache.GetOrCreateAsync(name, async entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
                entry.Size = 512;
                var secret = await _client.GetSecretAsync(name, ct);
                Console.WriteLine($"Cache miss - fetched '{name}' from Key Vault");
                return secret.Value.Value;
            }) ?? string.Empty;
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"SecretCache error for '{name}': {ex.Message}");
            throw;
        }
    }
}

